import json
data = json.load(open('/app/resources/treasury_bulletin_1956_03.json'))

def find_in_nested(obj, target_key, path=[]):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target_key.lower() in k.lower():
                print(f'Found: {path + [k]}')
                print(f'Value: {v}')
            yield from find_in_nested(v, target_key, path + [k])
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            yield from find_in_nested(item, target_key, path + [i])

# Search for exchange rate
list(find_in_nested(data, 'exchange'))
